/**
 * Concatenates supabase/migrations/*.sql, in filename order, into
 * supabase/setup.sql for a single paste into the Supabase SQL editor.
 *
 *   npm run supabase:bundle
 */

import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = process.cwd();
const dir = join(root, 'supabase', 'migrations');
const files = readdirSync(dir).filter((name) => name.endsWith('.sql')).sort();

const parts = [
  '-- Generated by scripts/bundle-migrations.mjs — do not edit.',
  '-- Paste this file into the Supabase SQL editor, or run `supabase db push`.',
  '',
];

for (const file of files) {
  parts.push(`-- ---------- ${file} ----------`, readFileSync(join(dir, file), 'utf8').trim(), '');
}

const target = join(root, 'supabase', 'setup.sql');
const body = parts.join('\n');
writeFileSync(target, body);
console.log(`supabase/setup.sql: ${files.length} migration(s), ${body.split('\n').length} lines`);

for (const file of files) console.log(`  ${file}`);
